<?php
require __DIR__.'/native_clients.php';
require APPPATH.'services/NativePortalRegistration.php';
$db->query('DROP TABLE '.$p.'contacts');
$db->query('CREATE TABLE '.$p.'contacts(id INTEGER PRIMARY KEY AUTOINCREMENT,userid INT NOT NULL,firstname TEXT NOT NULL,lastname TEXT NOT NULL,email TEXT NOT NULL,phonenumber TEXT NOT NULL,title TEXT NOT NULL,password TEXT NOT NULL,datecreated TEXT NOT NULL,active INT NOT NULL,is_primary INT NOT NULL,email_verified_at TEXT,email_verification_key TEXT,email_verification_sent_at TEXT,invoice_emails INT DEFAULT 0,credit_note_emails INT DEFAULT 0,estimate_emails INT DEFAULT 0,contract_emails INT DEFAULT 0,ticket_emails INT DEFAULT 0,project_emails INT DEFAULT 0,task_emails INT DEFAULT 0)');
$db->query('CREATE TABLE '.$p.'contact_permissions(userid INT NOT NULL,permission_id INT NOT NULL)');
$db->query('CREATE TABLE '.$p.'customfields(id INTEGER PRIMARY KEY,fieldto TEXT,field_order INT,active INT,only_admin INT,show_on_client_portal INT)');
if(!$db->table_exists($p.'emailtemplates'))$db->query('CREATE TABLE '.$p.'emailtemplates(emailtemplateid INTEGER PRIMARY KEY,issuer_id INT,slug TEXT,language TEXT)');
NativePortalRegistrationSchema::ensure($db,$p);NativePortalRegistrationSchema::ensure($db,$p);
$store=new CompanySettingsStorage($db,$p);foreach([41,82]as$i)$store->mutate($i,7,'update','allow_registration','1',null);
$writer=new NativePortalRegistration($db,$p,str_repeat('synthetic-only-',4));$start=$GLOBALS['essentialChecks'];$verifications=[];
$verify=function($issuer,$client,$contact,$key)use(&$verifications){$verifications[]=[$issuer,$client,$contact,$key];};
$input=['firstname'=>'Synthetic','lastname'=>'Public','email'=>'new-public@example.invalid','company'=>'Synthetic public company','password'=>'Synthetic-password-123','passwordr'=>'Synthetic-password-123'];$key=hash('sha256','registration-A');$hash=fn($v)=>password_hash($v,PASSWORD_DEFAULT);
$r=$writer->register(41,$key,$input,$hash,$verify);essentialCheck($r['client_id']>0&&$r['contact_id']>0&&!$r['replayed']&&count($verifications)===1,'public registration creates owned client/contact and calls internal verification once');
$owner=$db->query('SELECT owner_issuer_id,created_by FROM '.$p.'issuers_clients WHERE client_id=?',[$r['client_id']])->row_array();essentialCheck((int)$owner['owner_issuer_id']===41&&(int)$owner['created_by']===0,'public actor is not impersonated as staff and explicit ownership persists');
$again=$writer->register(41,$key,$input,$hash,$verify);essentialCheck($again['replayed']&&$again['client_id']===$r['client_id']&&count($verifications)===1,'replay cannot repeat insertion or verification');
essentialThrows(fn()=>$writer->register(41,$key,array_replace($input,['company'=>'Changed']),$hash,$verify),'native_portal_registration_conflict','request key binds exact normalized payload');
$b=$writer->register(82,hash('sha256','registration-B'),$input,$hash,$verify);essentialCheck($b['contact_id']!==$r['contact_id'],'same email in different issuers does not disclose or share customer');
essentialThrows(fn()=>$writer->register(41,hash('sha256','duplicate'),$input,$hash,$verify),'native_portal_registration_conflict','duplicate email within issuer is refused');
essentialThrows(fn()=>$writer->assertRegisteredInOwned($db,$p,41,'client',$r['client_id']),'native_custom_field_creation_denied','creation authority is not retained after transaction');
$before=(int)$db->query('SELECT COUNT(*) n FROM '.$p.'clients')->row()->n;
essentialThrows(fn()=>$writer->register(41,hash('sha256','verify-fail'),array_replace($input,['email'=>'rollback@example.invalid']),$hash,fn()=>throw new DomainException('synthetic_verification_fail')),'synthetic_verification_fail','verification failure aborts complete public registration');
essentialCheck((int)$db->query('SELECT COUNT(*) n FROM '.$p.'clients')->row()->n===$before,'failure leaves no partial customer');
$db->query('CREATE TRIGGER public_client_ignore BEFORE INSERT ON '.$p.'clients BEGIN SELECT RAISE(IGNORE); END');
essentialThrows(fn()=>$writer->register(41,hash('sha256','ignored'),array_replace($input,['email'=>'ignore@example.invalid']),$hash,$verify),'issuer_storage_failed','ignored customer insertion cannot reuse stale lastInsertId');$db->query('DROP TRIGGER public_client_ignore');
$store->mutate(41,7,'update','customers_register_require_confirmation','1',null);$pending=$writer->register(41,hash('sha256','pending'),array_replace($input,['email'=>'pending@example.invalid']),$hash,$verify);
essentialCheck((int)$db->query('SELECT active FROM '.$p.'contacts WHERE id=?',[$pending['contact_id']])->row()->active===0&&(int)$db->query('SELECT registration_confirmed FROM '.$p.'clients WHERE userid=?',[$pending['client_id']])->row()->registration_confirmed===0,'native approval policy keeps both new customer and contact inactive');
$store->mutate(41,7,'update','allow_registration','0',null);essentialThrows(fn()=>$writer->register(41,hash('sha256','disabled'),$input,$hash,$verify),'native_portal_registration_denied','disabled registration is denied before insertion');
echo 'Native portal registration: '.($GLOBALS['essentialChecks']-$start).' real SQLite checks passed; verification participant/HTTP remain separate.'.PHP_EOL;
